Method.Source:
    /// <summary>
    /// Filter customer lookup with AllowChargeThrough = Yes OR AllowCrossDock = Yes
    /// when called from the charge through invoice screen
    /// </summary>
    void init()
    {
        QueryBuildRange queryBuildRange;
        
        next init();

        Args args = this.args();

        if (args.caller().name() == formStr(METCBCTInvoiceForm))
        {
            Query q = this.CustTable_q;
            QueryBuildDataSource qbds = q.dataSourceTable(tableNum(CustTable));

            QueryBuildDataSource qbdsMETCustTable = qbds.addDataSource(tableNum(METCustTable));
            qbdsMETCustTable.joinMode(joinMode::InnerJoin);
            qbdsMETCustTable.relations(true);

            queryBuildRange = qbdsMETCustTable.addRange(fieldNum(METCustTable, AllowChargeThrough));
            queryBuildRange.value(strFmt('((%1 == %2) || (%3 == %2))', fieldStr(METCustTable, AllowChargeThrough), any2int(NoYes::Yes), fieldStr(METCustTable, AllowCrossDock)));

        }
    }
